package lazuli

import (
	"errors"
	"fmt"
	"strings"
)

var errNoDBResetTables = errors.New("lazuli: db reset requires at least one table")

// DBResetOptions configures SQL generated by BuildDBResetSQL.
type DBResetOptions struct {
	// DisableTriggers wraps the TRUNCATE with ALTER TABLE statements that
	// disable and then re-enable all triggers on each listed table.
	DisableTriggers bool
}

// BuildDBResetSQL builds ordered PostgreSQL statements for cleaning test data.
//
// Tables may be unqualified names such as "users" or schema-qualified names
// such as "app.users". Every identifier component must be made of ASCII
// letters, digits, and underscores, starting with a letter or underscore. The
// generated SQL quotes each identifier component and never opens a database
// connection.
func BuildDBResetSQL(tables []string, opts DBResetOptions) ([]string, error) {
	quotedTables, err := quoteDBResetTables(tables)
	if err != nil {
		return nil, err
	}

	statements := make([]string, 0, 1)
	if opts.DisableTriggers {
		statements = make([]string, 0, len(quotedTables)*2+1)
		for _, table := range quotedTables {
			statements = append(statements, buildDBResetTriggerSQL(table, "DISABLE"))
		}
	}

	statements = append(statements, "TRUNCATE TABLE "+strings.Join(quotedTables, ", ")+" RESTART IDENTITY CASCADE")

	if opts.DisableTriggers {
		for _, table := range quotedTables {
			statements = append(statements, buildDBResetTriggerSQL(table, "ENABLE"))
		}
	}

	return statements, nil
}

func quoteDBResetTables(tables []string) ([]string, error) {
	if len(tables) == 0 {
		return nil, errNoDBResetTables
	}

	quoted := make([]string, 0, len(tables))
	for _, table := range tables {
		quotedTable, err := quoteDBResetTable(table)
		if err != nil {
			return nil, err
		}
		quoted = append(quoted, quotedTable)
	}
	return quoted, nil
}

func quoteDBResetTable(table string) (string, error) {
	parts := strings.Split(table, ".")
	if len(parts) > 2 {
		return "", fmt.Errorf("lazuli: invalid db reset table name %q", table)
	}

	quoted := make([]string, 0, len(parts))
	for _, part := range parts {
		quotedPart, err := quoteDBResetIdentifier(part)
		if err != nil {
			return "", fmt.Errorf("lazuli: invalid db reset table name %q", table)
		}
		quoted = append(quoted, quotedPart)
	}
	return strings.Join(quoted, "."), nil
}

func quoteDBResetIdentifier(identifier string) (string, error) {
	if !validDBResetIdentifier(identifier) {
		return "", fmt.Errorf("invalid identifier %q", identifier)
	}
	return `"` + identifier + `"`, nil
}

func validDBResetIdentifier(identifier string) bool {
	if identifier == "" {
		return false
	}
	for i := 0; i < len(identifier); i++ {
		c := identifier[i]
		if i == 0 {
			if !isDBResetIdentifierLetter(c) && c != '_' {
				return false
			}
			continue
		}
		if !isDBResetIdentifierLetter(c) && !isDBResetIdentifierDigit(c) && c != '_' {
			return false
		}
	}
	return true
}

func isDBResetIdentifierLetter(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isDBResetIdentifierDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func buildDBResetTriggerSQL(table, action string) string {
	return "ALTER TABLE " + table + " " + action + " TRIGGER ALL"
}
